import { readFileSync,writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { resolve,dirname } from 'node:path';
import { CONVERSATIONS,CAST } from '../survival/src/content/story.js';
const out=dirname(fileURLToPath(import.meta.url)),repo=resolve(out,'../survival');
const sha=b=>createHash('sha256').update(b).digest('hex');
const source=readFileSync(resolve(repo,'src/content/story.js'));
const notice=JSON.parse(readFileSync(resolve(out,'reader.json'),'utf8')).notice;
const displaySpeaker=id=>id==='ren'?'REN':id==='ostrowski'?'OSTROWSKI':id==='system'?'':(CAST[id]?.name||String(id||'')).toUpperCase();
const groups=[],pins=[],audit=[];
let ci=0;
for(const [cid,c] of Object.entries(CONVERSATIONS)){
  ci++;const ids=Object.keys(c.nodes),map=new Map(ids.map((n,i)=>[n,`N${String(i+1).padStart(3,'0')}`]));
  const dest=n=>n==='end'||!n?'end of unit':map.get(n)||'outside selected unit';
  const unit={id:`U${ci}`,entry:(c.entry||[{goto:c.start||'start'}]).map(e=>dest(e.goto)),nodes:[],boundary_note:'Leaving this selected authored unit ends the excerpt; linked material outside is not represented as an executed event.'};
  groups.push({subject:displaySpeaker(c.who),units:[unit]});audit.push({conversation:cid,raw:c});
  const pin=(nid,field,text)=>pins.push({unit:unit.id,node:map.get(nid),coordinate:`${cid}:${nid}`,field,utf8_bytes:Buffer.byteLength(text),sha256:sha(text)});
  for(const [nid,n] of Object.entries(c.nodes)){
    if(n.text!==undefined)pin(nid,'text',n.text);
    const item={id:map.get(nid),speaker:displaySpeaker(n.speaker),text:n.text??null,state_dependent:false,alternates:[],continuations:n.next?[dest(n.next)]:(n.branch||[]).map(b=>dest(b.goto)),conditional_routing:!!n.branch,check_authored:false};
    if(n.mood){item.mood=n.mood;pin(nid,'mood',n.mood);}
    if(n.choices){
      item.continuations=n.choices.map((ch,i)=>`${map.get(nid)}C${i+1}`);
      for(let i=0;i<n.choices.length;i++){
        const ch=n.choices[i],id=`${map.get(nid)}C${i+1}`;pin(nid,`choices[${i}].text`,ch.text);
        const option={id,speaker:displaySpeaker('ren'),text:ch.text,state_dependent:!!ch.if&&Object.keys(ch.if).length>0,alternates:[],continuations:[dest(ch.goto)],conditional_routing:!!ch.if&&Object.keys(ch.if).length>0,check_authored:false,player_option:true};
        if(ch.tag){option.tag=ch.tag;pin(nid,`choices[${i}].tag`,ch.tag);}
        if(ch.why){option.locked_reason=ch.why;pin(nid,`choices[${i}].why`,ch.why);}
        unit.nodes.push(option);
      }
    }
    unit.nodes.push(item);
  }
}
const packageData={notice,subjects:groups};
for(const [name,data] of [['candidate-reader.json',packageData],['candidate-private-source-audit.json',audit],['candidate-field-pins.json',pins]])writeFileSync(resolve(out,name),JSON.stringify(data,null,2)+'\n');
const summary={status:'constructed; independent fidelity/context/presentation review pending; no blind comparison',commit:execFileSync('git',['rev-parse','HEAD'],{cwd:repo,encoding:'utf8'}).trim(),source_sha256:sha(source),build_sha256:sha(readFileSync(resolve(repo,'cinderline.1.0.0.js'))),authored_main_cast:Object.values(CAST).map(x=>x.full),conversation_units:ci,fields:pins.length,reader_sha256:sha(readFileSync(resolve(out,'candidate-reader.json'))),source_scope:'All thirteen conversation definitions and all their authored option text/tags/locked reasons, with effects and condition internals in coordinator-only audit. Speaker labels follow the actual English UI rule from src/ui/screens.js, rather than full cast biographies. Authored mood labels shown in that UI are retained. No biographies, goals, code comments or implementation scripts in reader. All conditional branches are alternatives, not an executed playthrough.',actual_play:'Keep the independently acquired production dialogues/endings and bible cross-check separate. This export is not new execution evidence.',limits:'No epilogue or actual observed delivery is represented by these conversation definitions. Candidate and reference topic/scope adequacy and presentation symmetry still need independent review.'};
writeFileSync(resolve(out,'candidate-manifest.json'),JSON.stringify(summary,null,2)+'\n');console.log(JSON.stringify(summary));
